export function getLandTransport(locationName: string, vehicleSize: VehicleSize) {
  const loc = LAND_TRANSPORT_TABLE[locationName];
  if (!loc) return null;
  const multiplier = SIZE_MULTIPLIERS[vehicleSize];
  return {
    baseCost: loc.basePrice,
    finalCost: Math.round(loc.basePrice * multiplier),
    terminal: loc.preferredTerminal,
    terminalName: TERMINAL_NAMES[loc.preferredTerminal],
    multiplier,
  };
}
